PI.getComponentAPI(\"Reference\").APIs(propertyName).hide();\n\t\t\t\tReactAPI.getComponentAPI(\"Label\").APIs(propertyName).hide();\n\t\t\t} \n\t\t}\n\t}\n})","name":"onload"},{"function":"//显示处理中遮罩\nReactAPI.openLoading(ReactAPI.international.getText(''EditView.notice.processing''));\n\n//获取提交的数据\nvar saveData = ReactAPI.getSaveData();\n\n//将空对象设置为Null\nif (saveData.sampleInfo.collectStaffId != null && saveData.sampleInfo.collectStaffId.id == \"\") {\n\tsaveData.sampleInfo.collectStaffId = null;\n}\nif (saveData.sampleInfo.inspectProjId != null && saveData.sampleInfo.inspectProjId.id == \"\") {\n\tsaveData.sampleInfo.inspectProjId = null;\n}\nif (saveData.sampleInfo.productId != null && saveData.sampleInfo.productId.id == \"\") {\n\tsaveData.sampleInfo.productId = null;\n}\nif (saveData.sampleInfo.psId != null && saveData.sampleInfo.psId.id == \"\") {\n\tsaveData.sampleInfo.psId = null;\n}\n\nvar signatureEnabled = ReactAPI.eSign.signatureEnabled({\n\tbuttonCode: \"LIMSSample_5.0.0.0_sample_sampleRegisterPart_BUTTON_register\"\n});\nif (signatureEnabled) {\n\t//启用电子签名\n\tReactAPI.eSign.openEsign({\n\t\tbuttonCode: \"LIMSSample_5.0.0.0_sample_sampleRegisterPart_BUTTON_register\",\n\t\tgetSignLog: function getSignLog(signatureLog) {\n\t\t\tdelete signatureLog.password1;\n\t\t\tdelete signatureLog.signatureEnabled;\n\t\t\tsubmitSampleRegiste(saveData, signatureLog);\n\t\t}\n\t});\n} else {\n\tsubmitSampleRegiste(saveData, null);\n}\nreturn false;","name":"onsave_es5"}]}';
DECLARE runtime_extra_view_existing_oid oid;
DECLARE runtime_extra_view_target_oid oid;
BEGIN
    SELECT udt_name = 'oid' INTO runtime_extra_view_json_is_oid
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'runtime_extra_view'
      AND column_name = 'view_json';
    IF COALESCE(runtime_extra_view_json_is_oid, false) THEN
        SELECT view_json INTO runtime_extra_view_existing_oid
        FROM public.runtime_extra_view
        WHERE code = 'LIMSSample_5.0.0.0_sample_sampleRegisterEdit';
        IF runtime_extra_view_existing_oid IS NOT NULL THEN
            IF EXISTS (
                SELECT 1
                FROM pg_largeobject_metadata
                WHERE oid = runtime_extra_view_existing_oid
            ) THEN
                IF convert_from(lo_get(runtime_extra_view_existing_oid), 'UTF8') = runtime_extra_view_payload THEN
                    runtime_extra_view_target_oid := runtime_extra_view_existing_oid;
                END IF;
            END IF;
        END IF;
        IF runtime_extra_view_target_oid IS NULL THEN
            runtime_extra_view_target_oid := lo_from_bytea(0, convert_to(runtime_extra_view_payload, 'UTF8'));
        END IF;
        INSERT INTO public.runtime_extra_view (code, ec_env, version, view_code, view_json, proj_flag)
        VALUES ('LIMSSample_5.0.0.0_sample_sampleRegisterEdit', 'product', 0, 'LIMSSample_5.0.0.0_sample_sampleRegisterEdit', runtime_extra_view_target_oid, false)
        ON CONFLICT (code) DO UPDATE SET
            ec_env = COALESCE(EXCLUDED.ec_env, public.runtime_extra_view.ec_env),
            version = GREATEST(COALESCE(public.runtime_extra_view.version, 0), EXCLUDED.version),
            view_code = EXCLUDED.view_code,
            view_json = EXCLUDED.view_json,
            proj_flag = COALESCE(public.runtime_extra_view.proj_flag, EXCLUDED.proj_flag);
    ELSE
        INSERT INTO public.runtime_extra_view (code, ec_env, version, view_code, view_json, proj_flag)
        VALUES ('LIMSSample_5.0.0.0_sample_sampleRegisterEdit', 'product', 0, 'LIMSSample_5.0.0.0_sample_sampleRegisterEdit', runtime_extra_view_payload, false)
        ON CONFLICT (code) DO UPDATE SET
            ec_env = COALESCE(EXCLUDED.ec_env, public.runtime_extra_view.ec_env),
            version = GREATEST(COALESCE(public.runtime_extra_view.version, 0), EXCLUDED.version),
            view_code = EXCLUDED.view_code,
            view_json = EXCLUDED.view_json,
            proj_flag = COALESCE(public.runtime_extra_view.proj_flag, EXCLUDED.proj_flag);
    END IF;
END $$;
