mponentAPI(''SupDataGrid'').APIs(''LIMSSample_5.0.0.0_sample_collectInfoEditdg1588760806379'').getDatagridData()[i].quantity;\n\t\tif (quantity != null) {\n\t\t\tselectData[i].quantity = quantity;\n\t\t}\n\t\tif (packNum != null) {\n\t\t\tselectData[i].packNum = packNum;\n\t\t}\n\t}\n}\n\nvar collectStaff = ReactAPI.getComponentAPI(\"Reference\").APIs(\"sampleInfo.collectStaffId.name\"); //处理人(取样人)\nvar collectTime = ReactAPI.getComponentAPI(\"DatePicker\").APIs(\"sampleInfo.collectTime\"); //取样时间\nvar memoField = ReactAPI.getComponentAPI(\"TextArea\").APIs(\"sampleInfo.memoField\"); //备注\n\nif (collectStaff.getValue().length != 0 && collectTime.getValue().length != 0) {\n\tvar signatureEnabled = ReactAPI.eSign.signatureEnabled({\n\t\tbuttonCode: \"LIMSSample_5.0.0.0_sample_collectListPart_BUTTON_collect\"\n\t});\n\n\tif (signatureEnabled) {\n\t\t//电子签名启用\n\t\t//打开电子签名\n\t\tReactAPI.eSign.openEsign({\n\t\t\tbuttonCode: \"LIMSSample_5.0.0.0_sample_collectListPart_BUTTON_collect\",\n\t\t\tgetSignLog: function getSignLog(signatureLog) {\n\t\t\t\tcollectSampleEdit(selectData, \"collectSampleSubmit\", memoField.getValue(), collectTime.getValue(), collectStaff.getValue()[0].id, signatureLog);\n\t\t\t}\n\t\t});\n\t} else {\n\t\tReactAPI.openLoading(ReactAPI.international.getText(''EditView.notice.processing''));\n\t\tcollectSampleEdit(selectData, \"collectSampleSubmit\", memoField.getValue(), collectTime.getValue(), collectStaff.getValue()[0].id, \"\");\n\t}\n}\nreturn false;","name":"onsave_es5"}]}', 0)
